// === Tab: mySketch ===
const GRID_SIZE = 200;
const SEED = Math.floor(Math.random() * 10000);
let CellPoints = [];


function setup() {
    createCanvas(800, 800);

    const rows = height / GRID_SIZE;
    const cols = width / GRID_SIZE;

    //グリッドセルごとにランダムなオフセットを持つポイントを生成
    //各ポイントはグリッド位置に基づくブール値も持つ
    for(let yi = -1; yi < rows + 1; yi++) {
        for(let xi = -1; xi < cols + 1; xi++) {
            const divVertical = (xi + yi) % 2 == 0;
            const p = new CellPoint(
                xi, yi,
                (xi + 0.5) * GRID_SIZE, 
                (yi + 0.5) * GRID_SIZE, 
                divVertical);
            CellPoints.push(p);
        }
    }
}

function draw() {
    background(255);
    randomSeed(SEED);

    AnimCellPoints();
    DrawGridGromCellPoints();
    //DrawGuide();
}


//----------------------🌀アニメーション-------------------------
function AnimCellPoints(){
    const noiseOffset = 0.005 * frameCount;
    const noiseScale = 100;
    for(let i = 0; i < CellPoints.length; i++) {
        const p = CellPoints[i];
        p.x = p.xi * GRID_SIZE + noise(p.xi * noiseScale , p.yi * noiseScale + noiseOffset) * GRID_SIZE;
        p.y = p.yi * GRID_SIZE + noise(p.yi * noiseScale, p.xi * noiseScale + noiseOffset) * GRID_SIZE;
    }
}


//----------------------🎨Grid描画-------------------------

function DrawGridGromCellPoints(){
    for(let i = 0; i < CellPoints.length; i++) {
        const p = CellPoints[i];
        fill(0);
        stroke(200);
        strokeWeight(5);
        DrawRectFromCellPoint(i);
    }
}


//ポイントの位置と分割方向を可視化
function DrawGuide(){
    for(let i = 0; i < CellPoints.length; i++) {
        const p = CellPoints[i];
        noStroke();
        if(p.divVertical) fill(255, 0, 0, 100);
        else fill(0, 0, 255, 100);
        rect(p.xi * GRID_SIZE, p.yi * GRID_SIZE, GRID_SIZE, GRID_SIZE);
        fill(255, 255, 0);
        ellipse(p.x, p.y, 10, 10);
    }
}

//----------------------🎨矩形描画-------------------------

//CellPointインデックスから矩形を描画
function DrawRectFromCellPoint(i){
	 if(i < 0 || i > CellPoints.length - 1)return;

	 const p0 = CellPoints[i];
    const p1 = GetPointByIndex(p0.xi - 1, p0.yi);
    const p2 = GetPointByIndex(p0.xi - 1, p0.yi - 1);
    const p3 = GetPointByIndex(p0.xi, p0.yi - 1);

    if(p1 == null || p2 == null || p3 == null) return;

    let topY, bottomY, leftX, rightX;
    if(p0.divVertical) {
        rightX = p0.x;
        leftX = p2.x;
        topY = p3.y;
        bottomY = p1.y;
    }else{
        rightX = p3.x;
        leftX = p1.x;
        topY = p2.y;
        bottomY = p0.y;
    }
    rect(leftX, topY, rightX - leftX, bottomY - topY, 100);
}


//----------------------📏ユーティリティ-------------------------

//Points配列の中から、指定インデックス(xi, yi)と一致するポイントを返す
function GetPointByIndex(xi, yi) {
    for(let i = 0; i < CellPoints.length; i++) {
        const p = CellPoints[i];
        if(p.xi == xi && p.yi == yi) {
            return p;
        }
    }
    return null;
}

//----------------------⚙️Class-------------------------

//グリッドセル内のポイントを表すクラス
class CellPoint {
    constructor(xi, yi, x, y, bool) {
        this.xi = xi;
        this.yi = yi;
        this.x = x;
        this.y = y;
        this.divVertical = bool;
    }
}




